import{_ as a,o as r,c as t,ag as i}from"./chunks/framework.DKalukzk.js";const n="/cours/assets/cgi-logo.DjWZsvA-.png",s="/cours/assets/batiment.DW3JNnlE.jpg",h=JSON.parse(`{"title":"Étude de cas — CGI à Québec","description":"Exemple guidé d'analyse d'une entreprise informatique de la région de Québec","frontmatter":{"title":"Étude de cas — CGI à Québec","description":"Exemple guidé d'analyse d'une entreprise informatique de la région de Québec"},"headers":[],"relativePath":"modules/04-analyse-info/04-etude-cgi.md","filePath":"modules/04-analyse-info/04-etude-cgi.md"}`),o={name:"modules/04-analyse-info/04-etude-cgi.md"};function l(p,e,c,d,u,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="etude-de-cas-—-cgi-a-quebec" tabindex="-1">Étude de cas — CGI à Québec <a class="header-anchor" href="#etude-de-cas-—-cgi-a-quebec" aria-label="Permalink to &quot;Étude de cas — CGI à Québec&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Cette entreprise sert d&#39;exemple pour le cours. <strong>Vous ne pouvez pas choisir CGI pour votre travail pratique.</strong></p></div><p>Ce tableau se retrouve une seule fois dans votre travail, en haut de la partie B.</p><table tabindex="0"><thead><tr><th>Entreprise</th><th>Secteur d&#39;activité</th><th>Localisation du siège social</th><th>Date de fondation</th></tr></thead><tbody><tr><td><a href="https://www.cgi.com/fr" target="_blank" rel="noreferrer">CGI</a></td><td>Services dans les domaines financiers, secteur public et industriel</td><td>Montréal, Québec, Canada</td><td>1976</td></tr></tbody></table><blockquote><p>Tableau 1 - Exemple de tableau synthèse pour l&#39;analyse d&#39;une entreprise</p></blockquote><h2 id="analyse-de-l-entreprise-cgi" tabindex="-1">Analyse de l&#39;entreprise CGI <a class="header-anchor" href="#analyse-de-l-entreprise-cgi" aria-label="Permalink to &quot;Analyse de l&#39;entreprise CGI&quot;">​</a></h2><figure class="my-6 max-w-xs"><img src="'+n+'" alt="Logo de CGI" class="img-bordered h-24 w-[80%] object-contain bg-white p-3"><figcaption> Logo de CGI. Source : <a href="https://logotyp.us/logo/cgi/" target="_blank" rel="noopener">logotyp.us</a></figcaption></figure><h3 id="breve-description-de-l-entreprise" tabindex="-1">Brève description de l&#39;entreprise <a class="header-anchor" href="#breve-description-de-l-entreprise" aria-label="Permalink to &quot;Brève description de l&#39;entreprise&quot;">​</a></h3><figure class="md:float-right md:ml-6 mb-4 md:w-80"><img src="'+s+'" alt="Bureaux de CGI" class="img-bordered w-[80%] object-cover"><figcaption> Bureaux de CGI. Source : <a href="https://maps.app.goo.gl/kfKZZZt3cN68Mv2Y6" target="_blank" rel="noopener">Google Maps</a></figcaption></figure><p>CGI est une <strong>entreprise privée</strong> spécialisée dans les services de conseil en technologie de l&#39;information (TI) et en management. Elle accompagne ses clients dans leur transformation numérique et l&#39;amélioration de leur rendement (<a href="https://www.cgi.com/fr" target="_blank" rel="noreferrer">CGI, 2026</a>). On peut distinguer trois grands pilliers de valeurs chez CGI:</p><ul><li>L&#39;esprit de propriété où les actionnaires sont des propriétaires;</li><li>L&#39;innovation créative;</li><li>La génération de résultats tangibles (<a href="https://www.cgi.com/fr" target="_blank" rel="noreferrer">CGI, 2026</a>).</li></ul><div class="clear-both"></div><h3 id="domaine-informatique-principal" tabindex="-1">Domaine informatique principal <a class="header-anchor" href="#domaine-informatique-principal" aria-label="Permalink to &quot;Domaine informatique principal&quot;">​</a></h3><p>De par son ampleur, on peut en déduire que CGI touche à la plupart des domaines en informatique. En se basant sur la page de carrières, on peut voir que les domaines actuellement en demande sont:</p><ul><li>le développement logiciel;</li><li>L&#39;infrastructure infonuagique;</li><li>L&#39;analyse de données et l&#39;intelligence artificielle (<a href="https://cgi.njoyn.com/corp/xweb/xweb.asp?CLID=21001&amp;page=joblisting&amp;lang=2" target="_blank" rel="noreferrer">Carrières CGI, 2026</a>).</li></ul><h3 id="poste-en-informatique-qu-on-peut-y-retrouver" tabindex="-1">Poste en informatique qu&#39;on peut y retrouver <a class="header-anchor" href="#poste-en-informatique-qu-on-peut-y-retrouver" aria-label="Permalink to &quot;Poste en informatique qu&#39;on peut y retrouver&quot;">​</a></h3><p>Un des postes actuellement recherchés à Québec est un Lead QA. Le Lead QA (Quality Assurance) est à la fois un expert technique et un leader d’équipe, capable de gérer des projets tout en soutenant la montée en compétences des ingénieurs QA (<a href="https://inforca.mc/carriere/fiches-metiers/test-informatique/lead-qa" target="_blank" rel="noreferrer">Inforca, 2026</a>).</p><p>Chez CGI, le Lead QA sera amené entre autres à concevoir, maintenir des tests automatisés et à faire évoluer les stratégies de tests. Comme c&#39;est un poste de responsable, il devra non seulement posséder des qualités techniques mais aussi des compétences de leadership, car il sera amené à encadrer des membres juniors de l&#39;équipe (<a href="https://cgi.njoyn.com/corp/xweb/xweb.asp?CLID=21001&amp;page=joblisting&amp;lang=2" target="_blank" rel="noreferrer">Carrières CGI, 2026</a>).</p><h2 id="bibliographie" tabindex="-1">Bibliographie <a class="header-anchor" href="#bibliographie" aria-label="Permalink to &quot;Bibliographie&quot;">​</a></h2><p>Voici un exemple de <strong>bibliographie en style APA</strong></p><p>Dans votre travail pratique, la bibliographie se retrouve <strong>une seule fois, à la fin du travail</strong>, et elle regroupe l&#39;ensemble des sources utilisées.</p><p>CGI. (2026). <em>CGI</em>. <a href="https://www.cgi.com/fr" target="_blank" rel="noreferrer">https://www.cgi.com/fr</a></p><p>CGI. (2026). <em>Carrières CGI</em>. <a href="https://cgi.njoyn.com/corp/xweb/xweb.asp?CLID=21001&amp;page=joblisting&amp;lang=2" target="_blank" rel="noreferrer">https://cgi.njoyn.com/corp/xweb/xweb.asp?CLID=21001&amp;page=joblisting&amp;lang=2</a></p><p>Inforca. (2026). <em>Lead QA</em>. <a href="https://inforca.mc/carriere/fiches-metiers/test-informatique/lead-qa" target="_blank" rel="noreferrer">https://inforca.mc/carriere/fiches-metiers/test-informatique/lead-qa</a></p>',24)])])}const f=a(o,[["render",l]]);export{h as __pageData,f as default};
